pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address anyone) public {
        // Ensure we are not the CEO to avoid side effects from DrugDealer
        vm.assume(anyone != 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        // The marketDrugs must be zero initially (since seedMarket hasn't been called)
        // We do not call seedMarket, so marketDrugs stays 0.
        // Act: prank as anyone and call DrugDealer
        vm.prank(anyone);
        // DrugDealer reverts if caller is not CEO, but we want to test the case where it doesn't revert
        // So we need to call it as CEO. But if we call it as CEO, it sets initialized to true only if seedMarket was called.
        // Actually the rule: after DrugDealer, initialized should remain false if marketDrugs is 0.
        // But DrugDealer only changes ceoAddress, not initialized. So initialized should stay as it was.
        // Since we haven't called seedMarket, initialized is false. Calling DrugDealer should not change it.
        // So we can call DrugDealer as CEO (but before seedMarket, it will revert because ceoAddress is the original CEO).
        // To avoid revert, we can call as the original CEO.
        // Let's call as the original CEO:
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        c.DrugDealer();
        // Now assert that initialized is false
        assertTrue(!c.initialized());
    }
}

