pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not the zero address (to avoid issues)
        vm.assume(caller != address(0));

        // Seed the market first so the contract is initialized
        // We need some initial marketDrugs and balance; let's do it via the owner
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Give the caller some ether to buy drugs later
        vm.deal(caller, 10 ether);

        // Let caller do some random actions to create state
        vm.prank(caller);
        c.buyDrugs{value: 1 ether}();

        // Capture state before DrugDealer()
        uint256 marketBefore = c.marketDrugs();
        // We need to check a referrer's claimedDrugs, but which address? Let's pick the caller's referrer if any
        address ref = c.referrals(caller);
        uint256 refClaimedBefore;
        if (ref != address(0)) {
            refClaimedBefore = c.claimedDrugs(ref);
        }

        // Call DrugDealer() which only changes ceoAddress
        // It requires msg.sender == ceoAddress; we can set ceoAddress to any address that we control
        address originalCEO = c.ceoAddress();
        vm.prank(originalCEO);
        c.DrugDealer();

        // Check that marketDrugs is unchanged
        uint256 marketAfter = c.marketDrugs();
        bool marketUnchanged = marketBefore == marketAfter;

        // Check that the referrer's claimedDrugs is unchanged (if there was a referrer)
        bool refClaimedUnchanged = true;
        if (ref != address(0)) {
            uint256 refClaimedAfter = c.claimedDrugs(ref);
            refClaimedUnchanged = refClaimedBefore == refClaimedAfter;
        }

        assertTrue(marketUnchanged && refClaimedUnchanged, "DrugDealer should not change marketDrugs or referral claim amounts");
    }
}

