        uint256 expectedNewKilo = drugsUsed / c.DRUGS_TO_PRODUCE_1KILO();

        vm.prank(caller);
        c.collectDrugs(ref);

        uint256 postKilos = c.getMyKilo();

        assertTrue(postKilos == preKilos + expectedNewKilo, "Kilos should increase by computed newKilo");
    }
