        uint256 drugsBought = c.calculateDrugBuy(ethAmount, contractBalanceBefore);
        uint256 expectedFee = c.devFee(drugsBought);
        uint256 expectedIncreaseCaller = drugsBought - expectedFee;
        uint256 expectedIncreaseRef = (drugsBought - expectedFee) / 5; // Since ref gets 1/5 of drugsUsed (which is claimedDrugs after buy)

