        // Because collectDrugs uses getMyDrugs which includes claimedDrugs[caller] after buy
        // But a simpler invariant: after buyDrugs, the increase in claimedDrugs[caller] is exactly drugsBought - devFee(drugsBought)
        uint256 actualIncreaseCaller = c.claimedDrugs(caller) - initClaimedCaller;
        assertTrue(actualIncreaseCaller == expectedIncreaseCaller, "claimedDrugs increase should equal drugsBought minus devFee(drugsBought)");
    }
}

